    def plant_errors(self, *, dataset=None, grow_um=None, grown=None, merges=None, missed=None, reveal=None, seed=None, splits=None):
        """Plant errors in a segmentation.

        For practice: a copy of a dataset's instrument segmentation with known errors planted in it
        (neighboring cells of different lineages merged, large cells split in two, cells missed,
        cells drawn too wide), simulated and named so (never promoted or exported), made as a job in
        the Segmentation view and recorded as a segmentation artifact with its answer key
        (planted.json). Compare it with the instrument's to find them. The same parameters (20
        merges, 20 splits, 10 missed, 10 grown by 1 µm, seed 20261014 if not given) answer the same
        artifact. Answers its summary, and with reveal the answer key.

        Args:
            dataset: A dataset of the project by name or id; the one in focus, else the first, if
                not given. Optional; a string.
            grow_um: How far a grown cell reaches into its neighbors, µm (1). Optional; a number.
            grown: Cells drawn too wide (10). Optional; a whole number.
            merges: Neighboring cells merged (20 if not given). Optional; a whole number.
            missed: Cells missed (10). Optional; a whole number.
            reveal: Answer the planted errors: each one's kind, cells and place. Optional; TRUE or
                FALSE (Python: True or False).
            seed: The seed choosing the cells (20261014). Optional; a whole number.
            splits: Cells split in two (20). Optional; a whole number.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("plant_errors", **{"dataset": dataset, "grow_um": grow_um, "grown": grown, "merges": merges, "missed": missed, "reveal": reveal, "seed": seed, "splits": splits})

    def export_segmentation(self, formats, folder, *, dataset=None, overwrite=None, segmentation=None):
        """Export a segmentation.

        Writes a segmentation of a dataset (its default if not named) into a folder, in the formats
        asked for: spatialdata (a SpatialData Zarr store: the cells as labels and polygons, the
        transcripts as points with their cells, the counts as an AnnData table; µm), anndata
        (AnnData Zarr), parquet and csv (cells, transcripts with their cells, outlines and counts,
        in Xenium's column names), mex (Matrix Market, as Read10X reads it), geojson (the outlines)
        and xenium-ranger (label masks for Xenium Ranger's import-segmentation, the inputs checked,
        and the command, which SituCraft does not run). A job in the Segmentation view;
        situcraft-export.json lists every file by its SHA-256 with the totals and content
        fingerprints every format holds. A folder that exists is replaced only with overwrite, and
        only when it is a SituCraft export; a segmentation with planted errors is refused. Needs the
        token (it writes files). Answers the manifest.

        Args:
            formats: spatialdata, anndata, parquet, csv, mex, geojson and xenium-ranger: one or
                more. Required; a vector of strings (Python: a list).
            folder: The export's folder, an absolute path; the export makes it. Required; a string.
            dataset: A dataset of the project by name or id; the one in focus, else the first, if
                not given. Optional; a string.
            overwrite: Replace the folder if it is an earlier SituCraft export. Optional; TRUE or
                FALSE (Python: True or False).
            segmentation: The segmentation, by name or artifact id (the dataset's default if not
                given). Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("export_segmentation", **{"formats": formats, "folder": folder, "dataset": dataset, "overwrite": overwrite, "segmentation": segmentation})

