    def samples(self):
        """List the samples.

        Lists the project's samples, in the Cohort view: each dataset is a sample, or its regions
        are instead (a tissue microarray's cores, sections on one slide). Answers each sample's
        name, its dataset and region (a region removed is flagged and left out of a cohort), its
        cells under its dataset's default segmentation (counted in its region), its region's area,
        its fields (the user's: subject, condition and any added; missing values null, never zero)
        and those read from its bundle (run, slide, Xenium region, panel, software), and the fields
        with their kinds.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("samples")

    def set_samples(self, *, fields=None, names=None, regions=None, remove_fields=None, table=None, values=None):
        """Describe the samples.

        Sets what is known of the project's samples, in one step (nothing changes if any part is
        refused): a dataset's regions made its samples instead of the dataset (or, with none, the
        dataset one sample again); fields added (text or number) or retyped (to a number only when
        every value is one); fields removed with their values; samples named; a table read (CSV or
        tab-separated text with a sample column: its rows matched to samples by name, its columns
        that are fields set, an empty cell clearing a value, its other columns added as fields, the
        bundles' columns left alone; rows naming no sample said); and values set by sample and field
        (null or an empty string clears). Answers the samples, as samples does.

        Args:
            fields: Fields to add or retype: [{name, kind (text or number; text if not given)}].
                Optional; a list of named lists (Python: a list of dicts).
            names: New names: {sample (name or ID): name}; an empty name gives back the dataset's or
                region's. Optional; a named list (Python: a dict).
            regions: A dataset's regions as its samples: {dataset (name or ID), regions (names or
                IDs; empty for the whole section)}. Optional; a named list (Python: a dict).
            remove_fields: Fields to remove, with their values. Optional; a vector of strings
                (Python: a list).
            table: A table of the samples' fields as CSV or tab-separated text, with a sample
                column. Optional; a string.
            values: Values: {sample (name or ID): {field: value}}; null or an empty string clears
                one. Optional; a named list (Python: a dict).

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("set_samples", **{"fields": fields, "names": names, "regions": regions, "remove_fields": remove_fields, "table": table, "values": values})

    def design(self, *, contrasts=None, covariates=None, exclude=None, group=None, pseudo_samples=None, reference=None, save=None, unit=None):
        """Describe the experimental design.

        Makes the cohort's experimental design from its samples, in the Cohort view, before any
        comparison of groups: the replicate unit (a field naming each biological replicate, such as
        subject), the field whose groups are compared and its reference level, the contrasts (each
        level against the reference if not given), covariates (fields, or the bundles' run, slide
        and panel: numbers as they are, text as factors) and samples left out with their reasons. A
        unit's samples in one group are technical replicates, combined into one row; a unit in more
        than one group pairs them (the units enter the model). Answers the design in words, its rows
        (units in groups, with their samples), its matrix's columns (treatment coding, as patsy's)
        and rows, its rank and residual degrees of freedom, the contrasts, the samples left out,
        notes, and, when it cannot be used, why: a group of fewer than two units, regions of one
        section as separate units (unless pseudo_samples, for teaching), a term confounded with
        another, no degrees of freedom left, or the groups confounded with a slide, run or panel.
        With save, keeps it in the project as a new version of that name. Without a unit or group,
        answers the latest saved design.

        Args:
            contrasts: Contrasts as [a, b] pairs, each a − b (each level against the reference if
                not given). Optional; a list of vectors (Python: a list of lists).
            covariates: Fields to adjust for: the user's, or run, slide, panel. Optional; a vector
                of strings (Python: a list).
            exclude: Samples left out: {sample (name or ID): reason}. Optional; a named list
                (Python: a dict).
            group: The field whose groups are compared, such as condition. Optional; a string.
            pseudo_samples: For a teaching example only: regions of one section given different
                units kept as pseudo-samples (not independent replicates), said so in the design and in
                every comparison made of it, instead of refused. Optional; TRUE or FALSE (Python: True
                or False).
            reference: The reference group (the first in code-point order if not given). Optional; a
                string.
            save: Keep the design in the project under this name, as its next version. Optional; a
                string.
            unit: The replicate unit: a field, such as subject. Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("design", **{"contrasts": contrasts, "covariates": covariates, "exclude": exclude, "group": group, "pseudo_samples": pseudo_samples, "reference": reference, "save": save, "unit": unit})

    def cohort_steps(self, *, graph=None, level=None, markers=None, questions=None, reference=None):
        """Run the same steps on every sample.

        Runs the same steps on every sample of the cohort, in the Cohort view: each dataset's cells
        clustered (SituCraft's defaults, on its default segmentation) and labeled from one marker
        set (a starter's resolved on the first dataset and used for the rest) or one labeled
        single-cell reference, so that every sample's labels have the same names; then a graph of
        each sample's cells (a region sample's, its region's; never those a review excluded) and the
        same questions asked of it with the same parameters: neighborhood enrichment over the graph,
        nearest distances, Moran's I. A step made already is answered at once. Answers the labels'
        source (the marker set or the reference) and, for each sample, its clustering, labels, graph
        and answers.

        Args:
            graph: The graph of each sample's cells: delaunay (the default), knn, radius or contact,
                with its default parameter. Optional; a string.
            level: The labels' level the questions are asked of (1, the first, if not given).
                Optional; a whole number.
            markers: The marker set: a project set's name or ID, or a starter's ID (SituCraft's
                starter set that fits the first sample's panel if not given). Optional; a string.
            questions: The questions: enrichment, distances, moran (enrichment if not given; [] for
                none). Optional; a vector of strings (Python: a list).
            reference: Instead of a marker set, a labeled single-cell reference on this computer, by
                its path (an AnnData object saved with write_zarr): every sample's cells labeled from
                it. Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("cohort_steps", **{"graph": graph, "level": level, "markers": markers, "questions": questions, "reference": reference})

    def summarize_samples(self, *, closing=None, level=None, markers=None, neighbors=None, niches=None, reference=None, samples=None):
        """Summarize the samples.

        Summarizes every sample of the cohort the same way, in the Cohort view, as an artifact of
        kind cohort-summary: each sample's cells by label (counts, shares of its labeled cells,
        densities per mm² of its tissue: the tissue window's area, within its region for a region
        sample), its niches' shares (niches found across the samples together, so that a niche is
        the same kind of place in every sample), its quality (cells, median transcripts, genes and
        areas, nuclei, transcripts per area), its graph's numbers, its answers' numbers (an
        enrichment's ratios, nearest distances' medians, Moran's I by gene) and its pseudobulk (each
        label's cells' transcripts summed gene by gene), each number traced to the artifact it came
        from. The samples are labeled from one marker set (cohort_steps labels them); the cohort's
        names are every label of the level. Answers the summary's ID, the cohort's labels, each
        sample's cells, labeled cells, counts by label, tissue and niches' shares, the niches (each
        one's defining labels), and the table's families.

        Args:
            closing: The tissue window's closing radius in µm (10 if not given). Optional; a number.
            level: The labels' level (1, the first, if not given). Optional; a whole number.
            markers: The marker set every sample is labeled from, by name or ID (the one the steps
                used, or the first that labels every sample, if not given). Optional; a string.
            neighbors: The labeled cells each cell's window holds, nearest first, in its own sample
                (10 if not given). Optional; a whole number.
            niches: The niches to find across the samples (6 if not given; 0 for none). Optional; a
                whole number.
            reference: Instead, the reference every sample is labeled from, by its path or SHA-256.
                Optional; a string.
            samples: Only these samples, by name or ID (every sample if not given). Optional; a
                vector of strings (Python: a list).

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("summarize_samples", **{"closing": closing, "level": level, "markers": markers, "neighbors": neighbors, "niches": niches, "reference": reference, "samples": samples})

    def cohort_table(self, *, family=None, keys=None, summary=None):
        """Read the cohort table.

        Reads a cohort summary's table, in the Cohort view: for one family of numbers (cells, share,
        density, niche, qc, graph, enrichment, nearest or moran), each sample's numbers by key with
        the artifact each came from. Answers the families, the keys and the samples' values.

        Args:
            family: cells (the default), share, density, niche, qc, graph, enrichment, nearest or
                moran. Optional; a string.
            keys: Only these keys (all if not given). Optional; a vector of strings (Python: a
                list).
            summary: The summary, by ID (the latest if not given). Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("cohort_table", **{"family": family, "keys": keys, "summary": summary})

    def cohort_qc(self, *, summary=None):
        """Read the cohort's QC.

        Reads a cohort summary's QC in the Cohort view, before any comparison: each sample's quality
        numbers (cells per mm², median transcripts and genes, transcripts per 100 µm², median cell
        and nucleus areas, the shares of cells with a nucleus and without a transcript; a nucleus's
        numbers null where the segmentation records none) with its bundle's run, slide and panel;
        the samples far out on one (a robust z-score, the median absolute deviation's, of 3.5 or
        more, and a difference that matters: 20% for a quantity, 5 points for a share), each with
        the reason, never passed or failed; the numbers' medians by slide, run and panel; the design
        draft's samples by batch and group, with what it says of a group confounded with a batch;
        the pseudobulk's principal components (each sample's scores, each component's share of the
        variance, over the genes every panel has); and the panels compared. Nothing is corrected for
        a batch unless the design adjusts for it.

        Args:
            summary: The summary, by ID (the latest if not given). Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("cohort_qc", **{"summary": summary})

    def compare_abundance(self, *, design=None, families=None, level=None, summary=None):
        """Compare the groups' abundances.

        Compares each label's cells between the design's groups, in the Cohort view, with the
        replicate unit (not the cell) as the unit, as an artifact of kind abundance made from the
        summary: each label's share of the labeled cells by a quasi-binomial generalized linear
        model of the design (its pairing and covariates), its density per mm² of tissue by a
        quasi-Poisson model with the tissue's area as offset, and the niches' shares as shares; each
        contrast's effect (an odds ratio or density ratio) with its interval, its t test on the
        residual degrees of freedom, the dispersion, and p-values adjusted by Benjamini and Hochberg
        over each family's tests, the universe said. The design is the Cohort view's draft unless a
        saved one is named. Answers every test.

        Args:
            design: A saved design, by name (its latest version; the Cohort view's draft if not
                given). Optional; a string.
            families: share, density, niche (share and density if not given). Optional; a vector of
                strings (Python: a list).
            level: The intervals' level (0.95 if not given). Optional; a number.
            summary: The summary, by ID (the one shown, or the latest, if not given). Optional; a
                string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("compare_abundance", **{"design": design, "families": families, "level": level, "summary": summary})

    def compare_expression(self, *, design=None, level=None, min_cells=None, summary=None):
        """Compare the groups' expression.

        Compares each label's genes between the design's groups, in the Cohort view, with the
        replicate unit (not the cell) as the unit, as an artifact of kind expression made from the
        summary: each label's pseudobulk (its cells' transcripts summed over each unit's samples)
        over the genes every panel has, in the units with enough of its cells; genes filtered by
        expression (a count of 10 over the median library size in the smallest group's number of
        units, and 15 in all); TMM normalization; voom's precision weights; each gene's weighted
        model of the design (its pairing and covariates) and limma's moderated t, its variance
        moderated toward the genes' prior; each contrast's log2 fold change with its interval, and
        p-values adjusted by Benjamini and Hochberg over every label, gene and contrast tested, the
        universe said. A label in too few units is left untested, with the reason. The design is the
        Cohort view's draft unless a saved one is named. Answers each label's genes below an
        adjusted p of 0.05 (and the 10 lowest p's of each), its units, genes tested and prior.

        Args:
            design: A saved design, by name (its latest version; the Cohort view's draft if not
                given). Optional; a string.
            level: The intervals' level (0.95 if not given). Optional; a number.
            min_cells: The fewest cells of a label a unit is tested with (10 if not given).
                Optional; a whole number.
            summary: The summary, by ID (the one shown, or the latest, if not given). Optional; a
                string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("compare_expression", **{"design": design, "level": level, "min_cells": min_cells, "summary": summary})

    def show_gene(self, gene, label, *, comparison=None):
        """Show a gene's expression by group.

        Shows a gene's expression in a label, by group, in the Cohort view's differential
        expression: each unit's log2 counts per million of the label's pseudobulk (its count and
        library size), with the gene's test of each contrast.

        Args:
            gene: The gene, by name. Required; a string.
            label: The label, by name. Required; a string.
            comparison: The expression comparison, by ID (the latest if not given). Optional; a
                string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("show_gene", **{"gene": gene, "label": label, "comparison": comparison})

    def compare_spatial(self, *, design=None, families=None, level=None, summary=None):
        """Compare the groups' spatial statistics.

        Compares the samples' spatial statistics between the design's groups, in the Cohort view,
        with the replicate unit as the unit (its samples' mean), as an artifact of kind
        spatial-comparison made from the summary: a pair of labels' neighbor enrichment (found over
        expected) and a label's median distance to the nearest cell of another, as log2 ratios; a
        gene's Moran's I (a niche's share is compared by compare_abundance). Each statistic in every
        unit is a linear model of the design (its pairing and covariates); each family's variances
        are moderated across its statistics (limma's empirical Bayes); each contrast's effect (a
        ratio, or a difference) with its interval and moderated t, and p-values adjusted by
        Benjamini and Hochberg over each family's tests, the universe said. A statistic some unit
        has none of is left untested. The summary's samples need a spatial question answered
        (summarize_samples). Answers every test.

        Args:
            design: A saved design, by name (its latest version; the Cohort view's draft if not
                given). Optional; a string.
            families: enrichment, nearest, moran (all the summary has if not given). Optional; a
                vector of strings (Python: a list).
            level: The intervals' level (0.95 if not given). Optional; a number.
            summary: The summary, by ID (the one shown, or the latest, if not given). Optional; a
                string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("compare_spatial", **{"design": design, "families": families, "level": level, "summary": summary})

    def show_sample_cells(self, sample, label, *, summary=None):
        """Show a sample's cells of a label.

        Shows a sample's cells of a label on its tissue, in the Viewer: of its cells chosen (its
        section's, or its region's; never those a review excluded), those whose label in the
        summary's label set is the one named. Answers the cells shown.

        Args:
            sample: The sample, by name or ID. Required; a string.
            label: The label, by name. Required; a string.
            summary: The summary, by ID (the latest if not given). Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("show_sample_cells", **{"sample": sample, "label": label, "summary": summary})

    def compare_panels(self):
        """Compare the samples' panels.

        Compares the gene panels of the project's samples (their bundles' gene_panel.json), before
        any summary: the panels (each one's name, design, version and genes, and the samples read
        with it), the genes every panel has (the only ones compared across samples), those in some
        panels only, shared genes read by other codewords, and genes whose Ensembl IDs or names
        differ.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("compare_panels")

    def export(self, what, path, *, coordinates=None, dataset=None, format=None, image=None, names=None, overwrite=None, project=None, regions=None, result=None, results=None, summary=None, title=None, transform=None):
        """Write a file.

        Writes a file: the project document (project, JSON), a project archive (archive, .scz: the
        project, its bundles recorded relative to the archive), the methods of a dataset, a result
        or the project with their references (methods, Markdown), a post-Xenium image's alignment as
        Xenium Explorer reads it (alignment: its transformation matrix, the image's pixels to the
        Xenium image's, or its landmarks as keypoints; CSV), a dataset's regions as QuPath imports
        annotations (regions: GeoJSON, in µm, the Xenium image's pixels or a post-Xenium image's), a
        dataset's reviews (reviews: CSV, a row a cell, cluster or region reviewed; or JSON, the
        record), the project's samples (samples: CSV, a row a sample with its fields and its
        bundle's), or a cohort summary's table (cohort-table: CSV, a row each number of each sample,
        with the artifact it came from) or pseudobulk (pseudobulk: CSV, a row a sample's label, a
        column a gene), what made a result (record: Markdown, JSON or BibTeX, as record answers it),
        a certificate (certificate: a zip of what a result, a dataset's results or the project rests
        on and reports, fingerprinted, with a README saying how situcraft verify checks it; answers
        its fingerprint), a report of results chosen (report: one HTML file, opened in any browser
        offline, of their figures, a table of each other result's numbers, each traced to its place
        in the certificate, the methods and their references, and the certificate itself, which the
        report checks as it opens; answers how many numbers it traces and the fingerprint), or a
        result package (package: the report, each saved view its figures show drawn in advance as
        tiles with a reader of its own, and the certificate, as a folder, or a zip when the path
        ends in .zip, that opens in any browser without SituCraft). A report and a package leave out
        where files lay on this computer, people's names and their notes, and with names: true the
        samples' and subjects' names; every text they hold is searched for them before they are
        written. Needs the token.

        Args:
            what: project, archive, methods, alignment, regions, reviews, samples, cohort-table,
                pseudobulk, record, certificate, report or package. Required; a string.
            path: The absolute path of the file to write (for a package, a folder that does not
                exist yet, or a .zip). Required; a string.
            coordinates: For regions: um (the default), xenium (the Xenium image's pixels) or a
                post-Xenium image by name or artifact ID (its pixels, as QuPath opens it). Optional; a
                string.
            dataset: A dataset of the project by name or id; the one in focus, else the first, if
                not given. Optional; a string.
            format: For an alignment: matrix (the default) or keypoints; for reviews: csv (the
                default) or json; for a record: markdown, json or bibtex (from the path's extension,
                .md, .json or .bib, if not given). Optional; a string.
            image: For an alignment: the image, by name or artifact ID. Optional; a string.
            names: For a report or a package: leave out the samples' and subjects' names (each
                written Sample 1, Subject 1, …). Optional; TRUE or FALSE (Python: True or False).
            overwrite: Replace the file if it exists. Optional; TRUE or FALSE (Python: True or
                False).
            project: For a record, methods or a certificate: the whole project's (a dataset's if
                neither this nor result is given). Optional; TRUE or FALSE (Python: True or False).
            regions: For regions: which, by name or ID (all if not given). Optional; a vector of
                strings (Python: a list).
            result: For a record, methods or a certificate: the result, by ID or name. Optional; a
                string.
            results: For a report or a package: the results it reports, by ID or name (figures among
                them); its figures first, then the others' tables in this order. Optional; a vector of
                strings (Python: a list).
            summary: For a cohort table or pseudobulk: the summary, by ID (the latest if not given).
                Optional; a string.
            title: For a report or a package: its title ("Results of" the project if not given).
                Optional; a string.
            transform: For an alignment: the version, by name or ID (the one in use if not given).
                Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("export", **{"what": what, "path": path, "coordinates": coordinates, "dataset": dataset, "format": format, "image": image, "names": names, "overwrite": overwrite, "project": project, "regions": regions, "result": result, "results": results, "summary": summary, "title": title, "transform": transform})

    def figure(self, *, center=None, columns=None, height_mm=None, name=None, panels=None, picture=None, picture_width=None, point_size=None, remove=None, scale_bar=None, size=None, text=None, views=None, width_um=None, file=None):
        """Make or change a figure.

        Makes or changes a figure of the project, in the Reports view: a page of panels (a journal's
        column, 85, 114 or 174 mm wide, or a 16:9 slide), each a saved view of the tissue at the
        figure's size (its stains composited from their samples, its cells' outlines and fill and
        its genes' transcripts, in µm, with a scale bar and a legend), lettered A, B, C in reading
        order. With views, the figure's panels are those views side by side; with panels, any panels
        (the tissue, a QC distribution, the cells' map, a spatial answer, a cohort's comparison,
        text) laid out in rows; either makes a new figure when none has the name. The tissue panels
        of a row share their images' height. Answers what it shows, each panel's letter, region in
        µm, µm a point, scale bar and the cells and transcripts it draws, and notes (a fill not
        drawn, too many transcripts). remove: true removes it.

        Args:
            center: Each tissue panel's center, [x, y] in µm (its view's if not given). Optional; a
                vector of numbers (Python: a list).
            columns: How many panels a row holds (as many as the panels, up to 3, if not given).
                Optional; a number.
            height_mm: The page's height in mm (the size's if not given). Optional; a number.
            name: The figure, by name or ID (a new one with views). Optional; a string.
            panels: The panels, in order, each an object of its kind: {kind: tissue, view,
                width_um?, center?, regions? (true for all, or their names)}; {kind: qc, dataset, metric
                (transcripts, total, area, nucleusArea), log?, filter?, segmentation?}; {kind: map, map,
                color? (clusters, or labels:<label set ID>:<level>)}; {kind: spatial, analysis
                (enrichment, distances or Moran's I)}; {kind: cohort, comparison, plot (forest, units,
                volcano, gene), family?, label?, gene?, contrast?, key?}; {kind: text, text}. Each names
                what it draws by name or ID; the title of any. Optional; a list of named lists (Python:
                a list of dicts).
            picture: Answer a picture of the figure too, as it draws now (a PNG): an agent gets it
                as an image. Optional; TRUE or FALSE (Python: True or False).
            picture_width: The picture's width in pixels (1,000; 300 to 2,000). Optional; a number.
            point_size: The transcripts' points, in pt across (1.2 if not given). Optional; a
                number.
            remove: Remove the figure. Optional; TRUE or FALSE (Python: True or False).
            scale_bar: The scale bar's length in µm (a round length about a fifth of the width if
                not given). Optional; a number.
            size: single (85 mm), onehalf (114 mm), double (174 mm, the default) or slide. Optional;
                a string.
            text: The text's size in pt (6 to 36; 7 if not given, 14 on a slide). Optional; a
                number.
            views: Saved views of the tissue, by name or ID, each a panel, side by side. Optional; a
                vector of strings (Python: a list).
            width_um: Each tissue panel's width of tissue in µm (what the view shows in a Viewer
                1,000 CSS pixels wide if not given). Optional; a number.
            file: Optional; ask for the picture and save it to this path (the tissue a JPEG, a map or a figure a PNG).

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        if file is not None and picture is None:
            picture = True
        result = self.call("figure", **{"center": center, "columns": columns, "height_mm": height_mm, "name": name, "panels": panels, "picture": picture, "picture_width": picture_width, "point_size": point_size, "remove": remove, "scale_bar": scale_bar, "size": size, "text": text, "views": views, "width_um": width_um})
        if file is not None:
            result.save_image(file)
        return result

    def write_figure(self, path, *, dpi=None, format=None, name=None, overwrite=None, time=None):
        """Write a figure.

        Writes a figure as SVG, PDF (vector, its text in Helvetica) or PNG (300 dpi by default), or
        its manifest as JSON, with its manifest inside: the figure, what each panel shows and was
        drawn from (the dataset by its bundle's run and fingerprint, the saved view, the artifacts
        drawn), a digest of each panel's drawing, SituCraft's version and commit, and a fingerprint.
        Answers the manifest's fingerprint and digests and each panel's facts. The same figure
        written at the same time is the same bytes in SVG and PDF.

        Args:
            path: The absolute path of the file to write. Required; a string.
            dpi: A PNG's resolution, and the stains' in every format (300 if not given). Optional; a
                number.
            format: svg, pdf, png or json (from the path's extension if not given). Optional; a
                string.
            name: The figure, by name or ID (the only one if not given). Optional; a string.
            overwrite: Replace the file if it exists. Optional; TRUE or FALSE (Python: True or
                False).
            time: The time written, ISO 8601 (now if not given): the same time, the same bytes.
                Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("write_figure", **{"path": path, "dpi": dpi, "format": format, "name": name, "overwrite": overwrite, "time": time})

    def record(self, *, dataset=None, format=None, project=None, result=None, time=None):
        """What made a result.

        Answers what made a result, as the Reports view shows it: each step from the bundles to it
        (a bundle, a segmentation, a clustering, a marker set, labels, a graph, an analysis, a
        design, a summary, a comparison, a figure…), in an order where each comes after the steps it
        was made from, with its method and version, its parameters and seed, the software that ran
        it, the decisions about it, and the publications it follows (numbered as first cited, each
        with its DOI). The result is any analysis, comparison, summary, label set, clustering, map,
        graph, segmentation, alignment, filter or figure of the project; or the record is of a
        dataset's results (dataset) or the whole project's (project). format markdown or bibtex also
        answers the record as that text; export (what: record) writes it to a file, and export
        (what: certificate) certifies it.

        Args:
            dataset: A dataset instead (its results), by name or ID. Optional; a string.
            format: json (the default), markdown or bibtex. Optional; a string.
            project: The whole project instead. Optional; TRUE or FALSE (Python: True or False).
            result: The result, by ID or name. Optional; a string.
            time: The time recorded, ISO 8601 (now if not given). Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("record", **{"dataset": dataset, "format": format, "project": project, "result": result, "time": time})

    def verify_records(self, steps):
        """Compute the page's records again.

        Used by situcraft verify: the page's own records named (a design, a filter, a figure, by ID)
        computed again in the project open, a design from its samples, a filter's cells from their
        attributes, a figure's drawing; answers each one's id, whether it was computed (checked),
        whether it is the same (same), how (detail) and what differs (differ).

        Args:
            steps: Each {id, kind (design, filter or figure), drawing (a figure's drawing as its
                certificate records it: {drawing, panels: [{id, letter, drawing}]})}. Required; a list
                of named lists (Python: a list of dicts).

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("verify_records", **{"steps": steps})

    def verify_certificate(self, *, dataset=None, path=None, project=None, result=None):
        """Verify a certificate.

        Verifies a certificate, a report or a result package as situcraft verify does, in SituCraft
        itself: each step SituCraft made is made again, in a SituCraft of its own, from the bundles
        this library knows (each project's datasets and the examples, found by their files'
        SHA-256), and every file compared bit for bit; the page's records are checked by their
        digests and its designs, filters and figures computed again in a headless browser. With
        path, the file there; with result, dataset or project, what made it, certified first.
        Answers the verdict (verified, differs or not checkable), each bundle found and each step's
        verdict, as verify's --report writes them. Needs the token with path (it reads the file).

        Args:
            dataset: A dataset of the project by name or id; the one in focus, else the first, if
                not given. Optional; a string.
            path: The absolute path of a certificate (.zip), a report (.html) or a result package
                (its folder or .zip). Optional; a string.
            project: Or the whole project's results: certified, then verified. Optional; TRUE or
                FALSE (Python: True or False).
            result: Or a result, by ID or name: certified, then verified. Optional; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("verify_certificate", **{"dataset": dataset, "path": path, "project": project, "result": result})

    def read_figure(self, path):
        """Read a figure back.

        Reads a figure SituCraft wrote (SVG, PDF, PNG or JSON) and compares it with the project:
        whether its manifest is as written, what changed since in each panel's view, dataset and
        artifacts, and whether each panel draws the same now.

        Args:
            path: The figure file on this computer. Required; a string.

        Returns:
            A Result: the message and the data SituCraft answered with.
        """
        return self.call("read_figure", **{"path": path})
